    s = ((name + ' kartınızın') if name else 'Kartınızın') + ' hesap kesim tarihi her ayın ' + str(wk) + '. haftası olarak tanımlı. '
    if ns and nl:
        s = s + 'Bir sonraki hesap kesim tarihiniz ' + sdate(ns) + ', son ödeme tarihiniz ' + sdate(nl) + '. '
