SUF = dict(bir="'dir", iki="'dir", üç="'tür", dört="'tür", beş="'tir", altı="'dır", yedi="'dir", sekiz="'dir", dokuz="'dur", on="'dur",
           yirmi="'dir", otuz="'dur", kırk="'tır", elli="'dir", altmış="'tır", yetmiş="'tir", seksen="'dir", doksan="'dır", yüz="'dür", bin="'dir")
