    return sdate(d) + SUF.get(last, "'dir")
def cop(t):
    t = t.rstrip()
    w = t.split(' ')[-1].lower()
    vow = [c for c in w if c in 'aıeioöuü']
    v = vow[-1] if vow else 'i'
    x = dict(a='ı', ı='ı', e='i', i='i', o='u', u='u', ö='ü', ü='ü')[v]
