# ---------------------------------------------------------------- 1. cards
nodes["get_cards"] = g.api_request("get_cards", pre("cards.list", {"customerNo": "{{customerNumber}}", "aiFlow": "CardOps"}, retries=1, fname="get_cards"), "cards_facts",
